<script setup lang="ts">const shop=useShop();const statuses=['Processing (demo)','Packed (demo)','Shipped (demo)','Completed (demo)','Cancelled (demo)'];function update(id:string,status:string){const order=shop.orders.find(o=>o.id===id);if(order){order.status=status;if(import.meta.client)localStorage.setItem('vy-orders-v1',JSON.stringify(shop.orders));shop.notify('Demo order status updated.')}} </script><template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-10"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">Admin demo</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">Orders<span class="text-brand">.</span></h1><p class="mt-3 text-sm text-gray-500">Change statuses for locally saved demo orders.</p><div v-if="shop.orders.length" class="mt-7 space-y-4"><article v-for="o in shop.orders" :key="o.id" class="rounded-2xl border border-gray-100 p-5"><div class="flex flex-wrap items-start justify-between gap-4"><div><p class="font-semibold">{{ o.id }}</p><p class="mt-1 text-xs text-gray-500">{{ o.customer.name }} · {{ o.customer.email }}</p><p class="mt-1 text-xs text-gray-500">{{ new Date(o.createdAt).toLocaleString() }}</p></div><p class="text-lg font-bold">${{ o.total.toFixed(2) }}</p></div><div class="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-gray-100 pt-4"><p class="text-xs text-gray-500">{{ o.items.map(i=>`${i.productName} × ${i.quantity}`).join(', ') }}</p><select :value="o.status" class="rounded-full border border-gray-200 bg-white px-3 py-2 text-xs" @change="update(o.id,($event.target as HTMLSelectElement).value)"><option v-for="s in statuses" :key="s">{{ s }}</option></select></div></article></div><EmptyState v-else title="No orders to review" description="Create a sample order from the storefront to test order management." to="/shop" action-label="Test checkout"/><NuxtLink to="/admin" class="mt-6 inline-block text-xs font-semibold text-gray-500">← Back to dashboard</NuxtLink></div></template>
